 check(SHGetDesktopFolder(&desktop)==S_OK&&desktop!=NULL,"desktop shell folder");attrs=SFGAO_FOLDER|SFGAO_FILESYSTEM;check(IShellFolder_ParseDisplayName(desktop,NULL,NULL,root,&eaten,&id,&attrs)==S_OK&&eaten==(ULONG)lstrlenW(root)&&(attrs&SFGAO_FOLDER),"parse absolute folder and attributes");check(SHGetPathFromIDListW(id,path)&&!lstrcmpW(root,path),"PIDL path round trip");check(IShellFolder_BindToObject(desktop,id,NULL,&IID_IShellFolder,(void**)&folder)==S_OK,"bind filesystem folder");
 Z7ShellJoin(root,L"DATA.TXT",from);create(from);attrs=SFGAO_FILESYSTEM|SFGAO_FOLDER;check(IShellFolder_ParseDisplayName(folder,NULL,NULL,L"DATA.TXT",NULL,&child,&attrs)==S_OK&&(attrs&SFGAO_FILESYSTEM)&&!(attrs&SFGAO_FOLDER),"parse relative file");check(IShellFolder_GetDisplayNameOf(folder,child,SHGDN_FORPARSING,&name)==S_OK&&name.uType==STRRET_WSTR&&!lstrcmpW(name.pOleStr,from),"parsing display name");CoTaskMemFree(name.pOleStr);
