 ZeroMemory(&fi,sizeof(fi));check(SHGetFileInfoW(from,0,&fi,sizeof(fi),SHGFI_DISPLAYNAME|SHGFI_SYSICONINDEX|SHGFI_SMALLICON|SHGFI_ICON)!=0&&fi.hIcon&&!lstrcmpW(fi.szDisplayName,L"DATA.TXT"),"display name and image list");DestroyIcon(fi.hIcon);
 id2=Z7ShellPidl(Z7_FILE,L"C:\\Unicode-\x03a9.txt");check(id2&&SHGetPathFromIDListW(id2,path)&&!lstrcmpW(path,L"C:\\Unicode-\x03a9.txt"),"Unicode PIDL round trip independent of FAT naming limits");CoTaskMemFree(id2);
 check(IShellFolder_GetUIObjectOf(folder,NULL,1,(LPCITEMIDLIST*)&child,&IID_IContextMenu,NULL,(void**)&menu)==S_OK,"create system context menu");popup=CreatePopupMenu();check(IContextMenu_QueryContextMenu(menu,popup,0,100,110,0)==6&&GetMenuItemCount(popup)==6,"populate context verbs");check(IContextMenu_GetCommandString(menu,2,GCS_VERBA,NULL,verb,sizeof(verb))==S_OK&&!lstrcmpA(verb,"copy"),"context canonical verb");ZeroMemory(&invoke,sizeof(invoke));invoke.cbSize=sizeof(invoke);invoke.lpVerb="copy";check(IContextMenu_InvokeCommand(menu,&invoke)==S_OK,"copy selection to clipboard");check(OpenClipboard(NULL),"read clipboard");clip=GetClipboardData(CF_HDROP);check(clip&&DragQueryFileW((HDROP)clip,0,path,Z7_PATH)&&!lstrcmpW(path,from),"clipboard retains path");CloseClipboard();DestroyMenu(popup);IContextMenu_Release(menu);
 check(IShellFolder_SetNameOf(folder,NULL,child,L"renamed.txt",0,&id2)==S_OK,"rename filesystem item");check(SHGetPathFromIDListW(id2,renamed)&&content(renamed),"rename preserves bytes");CoTaskMemFree(id2);CoTaskMemFree(child);
 ZeroMemory(&op,sizeof(op));ZeroMemory(from,sizeof(from));ZeroMemory(to,sizeof(to));lstrcpyW(from,renamed);Z7ShellJoin(root,L"copy.txt",to);op.wFunc=FO_COPY;op.pFrom=from;op.pTo=to;op.fFlags=FOF_NOCONFIRMATION|FOF_NOERRORUI;check(SHFileOperationW(&op)==0&&content(to),"shell copy preserves bytes");check(SHFileOperationW(&op)==0&&content(to),"explicit overwrite preserves bytes");op.wFunc=FO_DELETE;op.pFrom=to;op.pTo=NULL;op.fFlags|=FOF_ALLOWUNDO;check(SHFileOperationW(&op)==0&&GetFileAttributesW(to)==INVALID_FILE_ATTRIBUTES,"recoverable delete removes visible item");check(RegOpenKeyExW(HKEY_CURRENT_USER,L"Software\\7-Zip\\NT31 Recovery",0,KEY_QUERY_VALUE,&key)==0,"open recovery journal pointer");size=sizeof(record);check(RegQueryValueExW(key,L"LastRecord",NULL,&type,(BYTE*)record,&size)==0,"read recovery record");RegCloseKey(key);check(Z7ShellRestoreRecord(record)==0&&content(to),"restore recovers original path and bytes");
 op.fFlags&=~FOF_ALLOWUNDO;check(SHFileOperationW(&op)==0&&GetFileAttributesW(to)==INVALID_FILE_ATTRIBUTES,"explicit permanent delete");op.pFrom=from;op.wFunc=FO_MOVE;op.pTo=to;check(SHFileOperationW(&op)==0&&content(to)&&GetFileAttributesW(from)==INVALID_FILE_ATTRIBUTES,"move preserves bytes");op.pFrom=to;op.pTo=to;check(SHFileOperationW(&op)!=0&&content(to),"self move rejected without data loss");
