 check(RegCreateKeyExW(HKEY_CLASSES_ROOT,L".z7t",0,NULL,0,KEY_WRITE,NULL,&key,&status)==0&&status==REG_CREATED_NEW_KEY,"create isolated file association");check(RegSetValueExW(key,NULL,0,REG_SZ,(BYTE*)L"Z7ShellTest",24)==0,"set test association");RegCloseKey(key);check(RegCreateKeyExW(HKEY_CLASSES_ROOT,L"Z7ShellTest\\shell\\open\\command",0,NULL,0,KEY_WRITE,NULL,&key,&status)==0&&status==REG_CREATED_NEW_KEY,"create association command");wsprintfW(command,L"\"%s\" --child \"%%1\"",exe);check(RegSetValueExW(key,NULL,0,REG_SZ,(BYTE*)command,(lstrlenW(command)+1)*2)==0,"write association command");RegCloseKey(key);Z7ShellJoin(root,L"ASSOC.Z7T",path);create(path);exec.lpFile=path;exec.lpParameters=NULL;check(ShellExecuteExW(&exec)&&exec.hProcess,"association launch supplies process handle");check(WaitForSingleObject(exec.hProcess,10000)==WAIT_OBJECT_0&&GetExitCodeProcess(exec.hProcess,&status)&&status==37,"association command completes");CloseHandle(exec.hProcess);RegDeleteKeyW(HKEY_CLASSES_ROOT,L"Z7ShellTest\\shell\\open\\command");RegDeleteKeyW(HKEY_CLASSES_ROOT,L"Z7ShellTest\\shell\\open");RegDeleteKeyW(HKEY_CLASSES_ROOT,L"Z7ShellTest\\shell");RegDeleteKeyW(HKEY_CLASSES_ROOT,L"Z7ShellTest");RegDeleteKeyW(HKEY_CLASSES_ROOT,L".z7t");DeleteFileW(path);
 ZeroMemory(&browse,sizeof(browse));browse.pszDisplayName=path;browse.lpfn=callback;browse.ulFlags=BIF_RETURNONLYFSDIRS;id2=SHBrowseForFolderW(&browse);check(id2&&SHGetPathFromIDListW(id2,path)&&!lstrcmpW(path,root),"folder browser callback and selection");CoTaskMemFree(id2);browseCancel=TRUE;check(SHBrowseForFolderW(&browse)==NULL,"folder browser cancellation");
 DeleteFileW(to);CoTaskMemFree(id);IShellFolder_Release(folder);IShellFolder_Release(desktop);OleUninitialize();check(RemoveDirectoryW(root),"remove isolated test directory");check(TRUE,"ALL");CloseHandle(report);ExitProcess(0);
